using SparkFlow.Server.Application.Services; using SparkFlow.Server.Domain.Entities; namespace SparkFlow.Server.Application.Features.Workers.Heartbeat; public sealed class WorkerHeartbeatHandler { private readonly WorkerService _service; public WorkerHeartbeatHandler(WorkerService service){_service=service;} public Task<WorkerNode?> Handle(WorkerHeartbeatCommand command, CancellationToken cancellationToken=default)=>_service.HeartbeatAsync(command.WorkerId, command.IpAddress, cancellationToken);}
